using InventoryTracker.Api.Auth;

namespace InventoryTracker.Api.Domain;

/// <summary>
/// An order to make a quantity of one finished product (US-13 to US-21). Table <c>ProductionOrders</c>.
/// </summary>
/// <remarks>
/// <para>
/// The order number ("order #12") is the primary key, generated by the database from 1 (design 2.1, decision #22).
/// </para>
/// <para>
/// AC-05.3: each status the order reaches is recorded as a time and a user. The status history in responses
/// (design 5.7) is built from these four pairs; there is no history table, because each status is reached at
/// most once. Orders are never deleted (PRD section 5).
/// </para>
/// <para>
/// AC-15.10: at most one order may be InProduction. The send service checks this inside its write transaction,
/// and a unique filtered index on <see cref="Status"/> makes the database refuse a second one as a backstop.
/// </para>
/// </remarks>
public class ProductionOrder
{
    /// <summary>The order number and primary key, generated by the database.</summary>
    public int Number { get; set; }

    /// <summary>Foreign key to the finished product being made.</summary>
    public int FinishedProductId { get; set; }

    /// <summary>The finished product, when loaded.</summary>
    public Item FinishedProduct { get; set; } = null!;

    /// <summary>How much finished product was ordered; greater than 0.</summary>
    public decimal OrderedQuantity { get; set; }

    /// <summary>Current status. Stored as the enum name.</summary>
    public OrderStatus Status { get; set; }

    /// <summary>AC-05.3: when the order was created (UTC).</summary>
    public DateTime CreatedAt { get; set; }

    /// <summary>AC-05.3: foreign key to the Manager who created the order.</summary>
    public string CreatedById { get; set; } = string.Empty;

    /// <summary>The creator, when loaded.</summary>
    public AppUser CreatedBy { get; set; } = null!;

    /// <summary>AC-05.3: when materials were sent and the order became InProduction.</summary>
    public DateTime? SentAt { get; set; }

    /// <summary>AC-05.3: foreign key to the user who sent the materials.</summary>
    public string? SentById { get; set; }

    /// <summary>The sender, when loaded.</summary>
    public AppUser? SentBy { get; set; }

    /// <summary>AC-05.3: when the order was completed.</summary>
    public DateTime? CompletedAt { get; set; }

    /// <summary>AC-05.3: foreign key to the user who completed the order.</summary>
    public string? CompletedById { get; set; }

    /// <summary>The user who completed the order, when loaded.</summary>
    public AppUser? CompletedBy { get; set; }

    /// <summary>AC-05.3: when the order was cancelled.</summary>
    public DateTime? CancelledAt { get; set; }

    /// <summary>AC-05.3: foreign key to the Manager who cancelled the order.</summary>
    public string? CancelledById { get; set; }

    /// <summary>The user who cancelled the order, when loaded.</summary>
    public AppUser? CancelledBy { get; set; }

    /// <summary>The latest of the four status times; shown in order lists. Kept as a column so lists need no calculation.</summary>
    public DateTime StatusChangedAt { get; set; }

    /// <summary>The finished product actually made, entered at completion (US-19).</summary>
    public decimal? ProducedQuantity { get; set; }

    /// <summary>D-9: produced quantity − ordered quantity, set at completion.</summary>
    public decimal? OutputVariance { get; set; }

    /// <summary>D-9: output variance ÷ ordered quantity × 100, stored rounded to 6 places (architecture 3.1).</summary>
    public decimal? OutputVariancePercent { get; set; }

    /// <summary>AC-20.10: the tolerance in force when the order was completed, so later setting changes do not rewrite history.</summary>
    public decimal? ToleranceAtCompletionPercent { get; set; }

    /// <summary>The reason entered at completion (US-19), up to 500 characters.</summary>
    public string? CompletionReason { get; set; }

    /// <summary>The reason entered at cancellation (US-21), up to 500 characters.</summary>
    public string? CancellationReason { get; set; }

    /// <summary>One line per raw material, copied from the recipe when the order is created (AC-08.4).</summary>
    public List<ProductionOrderLine> Lines { get; set; } = [];
}
